            span[style*="color: rgb(240, 216, 255)"], div[style*="color: rgb(240, 216, 255)"] { color: #00f0ff !important; }
            span[style*="color: rgb(154, 120, 176)"], div[style*="color: rgb(154, 120, 176)"] { color: #ff007f !important; }
            svg[stroke*="#"] { stroke: #00f0ff !important; }
        `,
        'dracula': `
            div[style*="background-color: rgb(45, 27, 61)"] { background-color: #120000 !important; background-image: none !important; }
            div[style*="background-color: rgb(61, 37, 80)"] { background-color: #1a0000 !important; }
            .masyka-chat-card { background-color: #1f0000 !important; border: 1px solid #aa0000 !important; }
            span[style*="color: rgb(240, 216, 255)"], div[style*="color: rgb(240, 216, 255)"] { color: #ffcccc !important; }
            span[style*="color: rgb(154, 120, 176)"], div[style*="color: rgb(154, 120, 176)"] { color: #ff4444 !important; }
            svg[stroke*="#"] { stroke: #ff4444 !important; }
        `,
        'abyss': `
            div[style*="background-color: rgb(45, 27, 61)"] { background-color: #000a14 !important; background-image: none !important; }
            div[style*="background-color: rgb(61, 37, 80)"] { background-color: #001529 !important; }
            .masyka-chat-card { background-color: #001a33 !important; border: 1px solid #0055a4 !important; }
            span[style*="color: rgb(240, 216, 255)"], div[style*="color: rgb(240, 216, 255)"] { color: #cceeff !important; }
            span[style*="color: rgb(154, 120, 176)"], div[style*="color: rgb(154, 120, 176)"] { color: #00aaff !important; }
            svg[stroke*="#"] { stroke: #00aaff !important; }
        `,
        'synthwave': `
            div[style*="background-color: rgb(45, 27, 61)"] { background-color: #1a002a !important; background-image: none !important; }
            div[style*="background-color: rgb(61, 37, 80)"] { background-color: #260040 !important; }
            .masyka-chat-card { background-color: #2d004d !important; border: 1px solid #ff00ff !important; }
            span[style*="color: rgb(240, 216, 255)"], div[style*="color: rgb(240, 216, 255)"] { color: #ff99cc !important; }
            span[style*="color: rgb(154, 120, 176)"], div[style*="color: rgb(154, 120, 176)"] { color: #ffaa00 !important; }
            svg[stroke*="#"] { stroke: #ff00ff !important; }
        `,
        'ghost': `
            div[style*="background-color: rgb(45, 27, 61)"] { background-color: #111111 !important; background-image: none !important; }
            div[style*="background-color: rgb(61, 37, 80)"] { background-color: #1a1a1a !important; }
            .masyka-chat-card { background-color: #222222 !important; border: 1px solid #444 !important; }
            span[style*="color: rgb(240, 216, 255)"], div[style*="color: rgb(240, 216, 255)"] { color: #eeeeee !important; }
            span[style*="color: rgb(154, 120, 176)"], div[style*="color: rgb(154, 120, 176)"] { color: #888888 !important; }
            svg[stroke*="#"] { stroke: #cccccc !important; }
        `,
        'matcha': `
            div[style*="background-color: rgb(45, 27, 61)"] { background-color: #1a261a !important; background-image: none !important; }
            div[style*="background-color: rgb(61, 37, 80)"] { background-color: #1f2e1f !important; }
            .masyka-chat-card { background-color: #233323 !important; border: 1px solid #5c8a5c !important; }
            span[style*="color: rgb(240, 216, 255)"], div[style*="color: rgb(240, 216, 255)"] { color: #d9f2d9 !important; }
            span[style*="color: rgb(154, 120, 176)"], div[style*="color: rgb(154, 120, 176)"] { color: #8cbf8c !important; }
            svg[stroke*="#"] { stroke: #8cbf8c !important; }
        `,
        'royal': `
            div[style*="background-color: rgb(45, 27, 61)"] { background-color: #1a1600 !important; background-image: none !important; }
            div[style*="background-color: rgb(61, 37, 80)"] { background-color: #241e00 !important; }
            .masyka-chat-card { background-color: #2a2400 !important; border: 1px solid #cc9900 !important; }
            span[style*="color: rgb(240, 216, 255)"], div[style*="color: rgb(240, 216, 255)"] { color: #ffeeaa !important; }
            span[style*="color: rgb(154, 120, 176)"], div[style*="color: rgb(154, 120, 176)"] { color: #cca100 !important; }
            svg[stroke*="#"] { stroke: #ffcc00 !important; }
        `,
        'clear': '' // Пустая строка сбрасывает кастомную тему
    };

    // Настройки карточек для отображения в меню
    const themeConfigs = [
        { id: 'hacker', emoji: '💻', name: 'Хакер', c1: '#00ff00', c2: '#005500' },
        { id: 'neon', emoji: '🌃', name: 'Неон', c1: '#ff007f', c2: '#00f0ff' },
        { id: 'dracula', emoji: '🧛', name: 'Дракула', c1: '#ff4444', c2: '#880000' },
        { id: 'abyss', emoji: '🌊', name: 'Бездна', c1: '#00aaff', c2: '#001529' },
        { id: 'synthwave', emoji: '🌇', name: 'Ретро', c1: '#ff00ff', c2: '#ffaa00' },
        { id: 'ghost', emoji: '👻', name: 'Призрак', c1: '#ffffff', c2: '#555555' },
        { id: 'matcha', emoji: '🍵', name: 'Матча', c1: '#a6d9a6', c2: '#233323' },
        { id: 'royal', emoji: '👑', name: 'Золото', c1: '#ffcc00', c2: '#2a2400' }
    ];

    // Функция применения темы
    function applyTheme(name) {
        styleEl.innerHTML = themes[name] || '';
        localStorage.setItem('from-custom-theme', name); // Сохраняем выбор
    }

    // Восстанавливаем сохраненную тему при запуске
    applyTheme(localStorage.getItem('from-custom-theme') || 'clear');

    // Функция генерации карточки (кнопки)
    function createThemeCard(config) {
        const card = document.createElement('div');
        card.className = 'masyka-btn-press from-theme-btn';
        card.style.cssText = `position: relative; width: 90px; padding: 10px 6px; border-radius: 14px; background-color: #1a1a1a; border: 2.5px solid ${config.c1}; cursor: pointer; display: flex; flex-direction: column; align-items: center; gap: 6px; flex-shrink: 0;`;

        card.innerHTML = `
            <div style="width: 44px; height: 44px; border-radius: 12px; background-color: #2b2b2b; display: flex; align-items: center; justify-content: center; font-size: 22px;">${config.emoji}</div>
            <div style="display: flex; gap: 3px;">
                <div style="width: 12px; height: 12px; border-radius: 50%; background-color: ${config.c1}; border: 1px solid rgba(255,255,255,0.1);"></div>
                <div style="width: 12px; height: 12px; border-radius: 50%; background-color: ${config.c2}; border: 1px solid rgba(255,255,255,0.1);"></div>
            </div>
            <div style="font-size: 11px; font-weight: 600; color: #fff; text-align: center;">${config.name}</div>
        `;

        // При клике применяем тему
        card.onclick = () => applyTheme(config.id);
        return card;
    }

    // Слушатель изменений DOM (ждем, когда откроются "Настройки")
    const observer = new MutationObserver(() => {
        // Ищем контейнер с темами (ориентируемся по стандартной теме "Классика")
        const themeContainer = Array.from(document.querySelectorAll('div')).find(el => 
            el.textContent === 'Классика' && el.style.fontSize === '11px'
        )?.parentElement?.parentElement;

        // Если меню открыто и наши кнопки еще не добавлены
        if (themeContainer && !themeContainer.querySelector('.from-theme-btn')) {
            // Добавляем все наши темы в ленту
            themeConfigs.forEach(config => {
                themeContainer.appendChild(createThemeCard(config));
            });

            // Если пользователь кликнет на любую СТАНДАРТНУЮ тему, мы отключаем свои стили
            const standardThemes = themeContainer.querySelectorAll('.masyka-btn-press:not(.from-theme-btn)');
            standardThemes.forEach(btn => {
                btn.addEventListener('click', () => applyTheme('clear'));
            });
        }
    });

    // Запускаем слежение
    observer.observe(document.body, { childList: true, subtree: true });
})();
]]

-- Выполняем JS скрипт
app:executeJs(jsCode)

-- @name Звуки интерфейса (SoundFX)
-- @description Озвучка кнопок, чатов, печати текста и сворачивания приложения.
-- @icon 🔊

app:showToast("Загрузка звуков интерфейса...")

local jsCode = [[
    (function() {
        // Защита от дублирования
        if (window.__masykaSfxActive) return;
        window.__masykaSfxActive = true;

        // Предзагрузка звуков. Используем легкие .ogg файлы от Google
        const sounds = {
            click: new Audio('https://actions.google.com/sounds/v1/ui/button_click.ogg'),
            type: new Audio('https://actions.google.com/sounds/v1/ui/keyboard_typing_single_keystroke.ogg'),
            hide: new Audio('https://actions.google.com/sounds/v1/ui/pop_off.ogg'),
            show: new Audio('https://actions.google.com/sounds/v1/ui/pop_on.ogg')
        };

        // Настраиваем громкость (40%, чтобы не было слишком громко)
        Object.values(sounds).forEach(audio => {
            audio.volume = 0.4;
        });

        // Флаг, был ли первый клик (для обхода блокировки автоплея)
        let firstTouchDone = false;

        function playSound(type) {
            // Браузер не даст проиграть звук, пока юзер не тапнул по экрану хоть раз
            if (!firstTouchDone && type !== 'click') return; 

            try {
                // Клонируем звук, чтобы они могли накладываться при быстрой печати
                const sfx = sounds[type].cloneNode();
                sfx.volume = sounds[type].volume;
                sfx.play().catch(e => { /* Игнорируем ошибки автоплея в консоли */ });
            } catch (e) {}
        }

        // 1. Отслеживаем касания по интерактивным элементам (pointerdown работает быстрее click)
        document.addEventListener('pointerdown', function(e) {
            firstTouchDone = true;

            // Ищем, тапнул ли пользователь по кнопке, чату или иконке (на основе твоего HTML)
            const isInteractive = e.target.closest(
                'button, a, .masyka-btn-press, [data-msg-id], svg, textarea, input'
            );

            if (isInteractive) {
                playSound('click');
            }
        }, { passive: true });

        // 2. Отслеживаем печать в поле ввода
        // На мобилках keydown работает плохо, поэтому слушаем input (изменение текста)
        document.addEventListener('input', function(e) {
            if (e.target.tagName === 'TEXTAREA' || e.target.tagName === 'INPUT') {
                playSound('type');
            }
        }, { passive: true });

        // 3. Отслеживаем сворачивание/разворачивание
        document.addEventListener('visibilitychange', function() {
            if (document.hidden) {
                playSound('hide'); // Свернули
            } else {
                playSound('show'); // Развернули
            }
        });

    })();
]]

app:executeJs(jsCode)
